<script setup lang="ts">
import type { AssetKind, AssetRecord } from '../asset-api'
import { assetFields } from '../asset-forms'
defineProps<{ kind: AssetKind; form: Record<string, string>; editing?: boolean; companies?: AssetRecord[]; models?: AssetRecord[]; disabled?: boolean }>()
</script>
<template><div class="asset-fields"><template v-for="field in assetFields[kind]" :key="field.key"><div><label :for="`asset-${field.key}`">{{ field.label }}{{ field.required ? ' *' : '' }}</label><el-input v-if="field.type !== 'date'" :id="`asset-${field.key}`" v-model="form[field.key]" :type="field.type === 'textarea' ? 'textarea' : 'text'" :disabled="disabled || (editing && ['code','serialNumber'].includes(field.key))" /><input v-else :id="`asset-${field.key}`" v-model="form[field.key]" type="date" :disabled="disabled" /></div></template><template v-if="kind === 'devices'"><div><label for="asset-companyId">客户企业 *</label><el-input v-if="editing" id="asset-companyId" :model-value="form.companyId" disabled/><el-select v-else id="asset-companyId" v-model="form.companyId" :disabled="disabled || editing" placeholder="先选择启用的客户企业"><el-option v-for="item in companies" :key="item.id" :value="item.id" :label="`${item.code} · ${item.name}`" /></el-select><p v-if="editing" class="muted small">本批不提供转归属，企业不可普通编辑。</p></div><div><label for="asset-modelId">产品型号 *</label><el-input v-if="editing" id="asset-modelId" :model-value="form.modelId" disabled/><el-select v-else id="asset-modelId" v-model="form.modelId" :disabled="disabled || editing" placeholder="选择启用的产品型号"><el-option v-for="item in models" :key="item.id" :value="item.id" :label="`${item.code} · ${item.name}`" /></el-select></div></template></div></template>
